  const d = new Date(iso)
  return new Intl.DateTimeFormat("en-US", {
    month: "numeric", day: "numeric", year: "numeric",
    hour: "numeric", minute: "2-digit", second: "2-digit",
    timeZoneName: "short",
  }).format(d)
}

function formatDuration(ms: number): string {
  if (ms >= 1000) return (ms / 1000).toFixed(1) + "s"
  return ms + "ms"
}

// ---------------------------------------------------------------------------
// Title
// ---------------------------------------------------------------------------

function extractTitle(text: string): string {
  const s = text.replace(/^["'\s]+|["'\s]+$/g, "").split("\n")[0].trim().slice(0, 60)
  return s ? s.charAt(0).toUpperCase() + s.slice(1) : "Untitled"
}

// ---------------------------------------------------------------------------
// YAML builder
// ---------------------------------------------------------------------------

function escYAML(v: unknown): string {
  if (typeof v === "string") {
    if (v === "") return '""'
    const needsBlock = v.includes("\n") || v.length > 80
    if (needsBlock) return "|\n" + v.split("\n").map(l => "  " + l).join("\n")
    return JSON.stringify(v)
  }
  if (typeof v === "number" || typeof v === "boolean") return String(v)
  return JSON.stringify(v)
}

function yamlLines(depth: number, fields: Record<string, unknown>): string[] {
  const pad = "  ".repeat(depth)
  const out: string[] = []
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined || v === null) continue
    if (typeof v === "object" && !Array.isArray(v)) {
      out.push(`${pad}${k}:`)
      out.push(...yamlLines(depth + 1, v as Record<string, unknown>))
    } else if (Array.isArray(v)) {
      if (v.length === 0) { out.push(`${pad}${k}: []`); continue }
      out.push(`${pad}${k}:`)
      for (const item of v) {
        if (typeof item === "object") {
          const sub = Object.entries(item as Record<string, unknown>)
            .filter(([, sv]) => sv !== undefined && sv !== null)
            .map(([sk, sv]) => `    ${sk}: ${escYAML(sv)}`)
            .join("\n")
          out.push(`  - ${sub}`)
        } else {
          out.push(`  - ${escYAML(item)}`)
        }
      }
    } else {
      out.push(`${pad}${k}: ${escYAML(v)}`)
    }
  }
  return out
}

function buildYAML(docs: Record<string, unknown>[]): string {
  return docs.map(d => "---\n" + yamlLines(0, d).join("\n") + "\n").join("")
