// Turn model
// ---------------------------------------------------------------------------

interface ToolCall {
  tool: string; args: string; result: string
}

class Turn {
  userText = ""
  modelID: string | null = null
  thinking: string[] = []
  responseText: string[] = []
  toolCalls: ToolCall[] = []
  startTime = ts()
  endTime: string | null = null
  pendingTool: string | null = null
  pendingArgs: string | null = null
  userMessageID: string | null = null

  toFields(): Record<string, unknown> {
    const a: Record<string, unknown> = { model: this.modelID }
    if (this.thinking.length > 0) a.thinking = this.thinking.join("")
    if (this.responseText.length > 0) a.response = this.responseText.join("")
    if (this.toolCalls.length > 0) {
      a.tool_calls = this.toolCalls.map((tc) => ({ tool: tc.tool, args: tc.args, result: tc.result }))
    }
    if (this.startTime && this.endTime) {
      const ms = new Date(this.endTime).getTime() - new Date(this.startTime).getTime()
      a.duration = formatDuration(ms)
      a.duration_ms = ms
    }
    return { user: this.userText, assistant: a }
  }
}

