interface MsgInfo {
  role: string; sessionID: string | null; modelID: string | null
}
const msgStore = new Map<string, MsgInfo>()

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

export const OpenCodeLogger: Plugin = async () => {
  return {
    event: async ({ event }) => {
      try {
        const p = (event as any).properties
        const now = ts()

        switch (event.type) {
          case "session.created": {
            const info = p?.info
            if (!info?.id) break
            sid = info.id
            model = info.modelID ?? info.model ?? null
            created = now
            updated = now
            title = "Untitled"
            turn = null
            turns = []
            msgStore.clear()
            writeJSONL(sid, { timestamp: now, sessionID: sid, type: "session.created", model })
            break
          }

          case "message.updated": {
            const info = p?.info
            if (!info?.id) break
            msgStore.set(info.id, {
              role: info.role,
              sessionID: info.sessionID ?? null,
              modelID: info.modelID ?? null,
            })
            if (info.role === "assistant" && info.modelID) model = info.modelID
            break
          }

          case "message.part.updated": {
            const part = p?.part
            if (!part?.messageID) break
            const mi = msgStore.get(part.messageID)
            const role = mi?.role ?? "unknown"
            const ses = mi?.sessionID ?? sid
            if (!ses) break

            if (role === "user" && part.type === "text" && (!turn || turn.userMessageID !== part.messageID)) {
              turn = new Turn()
              turn.userText = part.text ?? ""
              turn.modelID = model
              turn.userMessageID = part.messageID
              turn.startTime = ts()
              if (title === "Untitled") {
                title = extractTitle(part.text ?? "")
              }
            }

            const entry: Record<string, unknown> = {
              timestamp: ts(), sessionID: ses, type: "message.part", role,
              partType: part.type, modelID: model, messageID: part.messageID,
            }

            switch (part.type) {
              case "text":
                entry.text = part.text ?? ""
                if (turn && role === "assistant") turn.responseText.push(part.text ?? "")
                break
              case "reasoning":
                entry.reasoning = part.text ?? part.reasoning ?? ""
                if (turn && role === "assistant") turn.thinking.push(part.text ?? part.reasoning ?? "")
                break
              case "tool_call":
                entry.toolCallID = part.toolCallID ?? ""
                entry.toolName = part.toolName ?? ""
                entry.args = part.args ?? ""
                if (turn) { turn.pendingTool = part.toolName ?? ""; turn.pendingArgs = part.args ?? "" }
                break
              case "tool_result":
                entry.toolCallID = part.toolCallID ?? ""
                entry.result = part.data ?? part.text ?? ""
                if (turn && turn.pendingTool) {
                  turn.toolCalls.push({
                    tool: turn.pendingTool, args: turn.pendingArgs ?? "",
                    result: part.data ?? part.text ?? "",
                  })
                  turn.pendingTool = null; turn.pendingArgs = null
                }
                break
              default:
                entry.text = part.text ?? ""
            }

            writeJSONL(ses, entry)
            break
          }

          case "session.status": {
            const props = p?.properties ?? p
            if (props?.status?.type !== "idle") break
            const ses = props?.sessionID ?? sid
            if (!ses) break

            if (turn) {
              turn.endTime = ts()
              turns.push(turn.toFields())
            }
            updated = ts()

            writeJSONL(ses, { timestamp: ts(), sessionID: ses, type: "turn.complete", turnIndex: turns.length - 1 })

            // Rewrite YAML with updated header + all accumulated turns
            const yp = join(LOG_BASE, `${ses}.yaml`)
            const header: Record<string, unknown> = {
              title,
              session: { id: ses, created: formatLocal(created!), updated: formatLocal(updated) },
              model,
            }
            writeFileSync(yp, buildYAML([header, ...turns]))
            turn = null
            break
          }

          case "session.compacted": {
            const ses = p?.sessionID ?? sid
            if (!ses) break
            writeJSONL(ses, { timestamp: ts(), sessionID: ses, type: "session.compacted" })
            break
          }

          case "session.deleted":
          case "server.instance.disposed": {
            const info = p?.info
            const ses = event.type === "session.deleted" ? (info?.id ?? sid) : sid
            if (!ses) break
            writeJSONL(ses, {
              timestamp: ts(), sessionID: ses,
              type: event.type === "session.deleted" ? "session.deleted" : "server.shutdown",
            })
            if (sid === ses) sid = null
            break
          }
        }
      } catch { /* no crash */ }
    },
  }
}
"}

