<｜｜DSML｜｜parameter name="content" string="true">import type { Plugin } from "@opencode-ai/plugin"
import { mkdirSync, appendFileSync, writeFileSync } from "node:fs"
import { join } from "node:path"

const LOG_BASE = ".opencode/logs"

function ts(): string {
  return new Date().toISOString()
}

function j(o: unknown): string {
  try {
    return JSON.stringify(o)
  } catch {
    return JSON.stringify({ error: "serialize failed" })
  }
}

// ---------------------------------------------------------------------------
// JSONL
// ---------------------------------------------------------------------------

function writeJSONL(sessionID: string, entry: Record<string, unknown>) {
  try {
    mkdirSync(LOG_BASE, { recursive: true })
    appendFileSync(join(LOG_BASE, `${sessionID}.jsonl`), j(entry) + "\n")
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

// ---------------------------------------------------------------------------
// YAML helpers
// ---------------------------------------------------------------------------

function escYAML(v: string): string {
  if (!v) return '""'
  const hasSpecial = v.includes("\n") || v.includes(": ") || v.includes("#") || v.length > 80
  if (hasSpecial) {
    return "|\n" + v.split("\n").map((l) => "  " + l).join("\n")
  }
  return JSON.stringify(v)
}

function yamlFields(fields: Record<string, unknown>, indent: number): string[] {
  const lines: string[] = []
  const pad = "  ".repeat(indent)
  for (const [k, v] of Object.entries(fields)) {
    if (v === undefined || v === null) continue
    if (typeof v === "string") {
      const e = escYAML(v)
      lines.push(e.startsWith("|") ? `${pad}${k}: ${e}` : `${pad}${k}: ${e}`)
    } else if (typeof v === "number" || typeof v === "boolean") {
      lines.push(`${pad}${k}: ${v}`)
    } else if (Array.isArray(v)) {
      if (v.length === 0) {
        lines.push(`${pad}${k}: []`)
      } else {
        lines.push(`${pad}${k}:`)
        for (const item of v) {
          if (typeof item === "object") {
            const sub = Object.entries(item as Record<string, unknown>)
              .filter(([, vv]) => vv !== undefined && vv !== null)
              .map(([sk, sv]) => {
                if (typeof sv === "string") {
                  const e = escYAML(sv)
                  if (e.startsWith("|")) {
                    return `    ${sk}: ${e.split("\n").map((l, i) => i === 0 ? l : "    " + l).join("\n")}`
                  }
                  return `    ${sk}: ${e}`
                }
                return `    ${sk}: ${sv}`
              })
              .join("\n")
            lines.push(`  - ${sub}`)
          }
        }
      }
    } else if (typeof v === "object") {
      lines.push(`${pad}${k}:`)
      lines.push(...yamlFields(v as Record<string, unknown>, indent + 1))
    }
  }
  return lines
}

function writeYAMLDoc(path: string, fields: Record<string, unknown>) {
  try {
    mkdirSync(LOG_BASE, { recursive: true })
    const rendered = yamlFields(fields, 0)
    if (rendered.length > 0) {
      appendFileSync(path, "---\n" + rendered.join("\n") + "\n")
    }
  } catch {
    // Plugin failures must not crash OpenCode
  }
}

// ---------------------------------------------------------------------------
// Turn buffer
// ---------------------------------------------------------------------------

interface ToolCallRecord {
  tool: string
  args?: string
  result?: string
}

class TurnBuf {
  userText = ""
  modelID: string | null = null
  thinking: string[] = []
  responseText: string[] = []
  toolCalls: ToolCallRecord[] = []
  startTime = ts()
  endTime: string | null = null
  pending: ToolCallRecord | null = null
  userMessageID: string | null = null

  toYAMLDoc(): Record<string, unknown> {
    const asst: Record<string, unknown> = {}
    if (this.modelID) asst.model = this.modelID
    if (this.thinking.length > 0) asst.thinking = this.thinking.join("")
    if (this.responseText.length > 0) asst.response = this.responseText.join("")
    if (this.toolCalls.length > 0) {
      asst.tool_calls = this.toolCalls.map((tc) => ({
        tool: tc.tool,
        args: tc.args ?? "",
        result: tc.result ?? "",
      }))
    }
    if (this.startTime && this.endTime) {
      asst.duration_ms = new Date(this.endTime).getTime() - new Date(this.startTime).getTime()
    }
    return { user: this.userText, assistant: asst }
  }
}

// ---------------------------------------------------------------------------
// State
// ---------------------------------------------------------------------------

let currentSessionID: string | null = null
let sessionModel: string | null = null
let sessionCreated: string | null = null
let headerWritten = false
let turn: TurnBuf | null = null
const messageRoles = new Map<string, string>()

// ---------------------------------------------------------------------------
// Plugin
// ---------------------------------------------------------------------------

export const OpenCodeLogger: Plugin = async () => {
  return {
    event: async ({ event }) => {
      try {
        const p = (event as any).properties

        switch (event.type) {
          case "session.created": {
            const info = p?.info
            if (!info?.id) break
            currentSessionID = info.id
            sessionModel = info.modelID ?? info.model ?? null
            sessionCreated = ts()
            headerWritten = false
            turn = null
            messageRoles.clear()
            writeJSONL(info.id, {
              timestamp: sessionCreated,
              sessionID: info.id,
              type: "session.created",
              model: sessionModel,
            })
            break
          }

          case "message.updated": {
            const info = p?.info
            if (!info?.id) break
            if (info.role) messageRoles.set(info.id, info.role)
            if (info.role === "assistant" && info.modelID) {
              sessionModel = info.modelID
            }
            break
          }

          case "message.part.updated": {
            const part = p?.part
            if (!part?.messageID) break

            // Get role from the message store (populated by message.updated)
            const role = messageRoles.get(part.messageID) ?? "unknown"
            const sessionID = p?.message?.sessionID ?? currentSessionID
            if (!sessionID) break

            // Start new turn on first user text part
            if (role === "user" && part.type === "text" && (!turn || turn.userMessageID !== part.messageID)) {
              turn = new TurnBuf()
              turn.userText = part.text ?? ""
              turn.modelID = sessionModel
              turn.userMessageID = part.messageID
              turn.startTime = ts()
            }

            const entry: Record<string, unknown> = {
              timestamp: ts(),
              sessionID,
              type: "message.part",
              role,
              partType: part.type,
              modelID: sessionModel,
              messageID: part.messageID,
            }

            switch (part.type) {
              case "text":
                entry.text = part.text ?? ""
                if (turn && role === "assistant") turn.responseText.push(part.text ?? "")
                break
              case "reasoning":
                entry.reasoning = part.text ?? part.reasoning ?? ""
                if (turn && role === "assistant") turn.thinking.push(part.text ?? part.reasoning ?? "")
                break
              case "tool_call":
                entry.toolCallID = part.toolCallID ?? ""
                entry.toolName = part.toolName ?? ""
                entry.args = part.args ?? ""
                if (turn) {
                  turn.pending = { tool: part.toolName ?? "", args: part.args ?? "" }
                }
                break
              case "tool_result":
                entry.toolCallID = part.toolCallID ?? ""
                entry.result = part.data ?? part.text ?? ""
                if (turn && turn.pending && turn.pending.tool === part.toolName) {
                  turn.pending.result = part.data ?? part.text ?? ""
                  turn.toolCalls.push(turn.pending)
                  turn.pending = null
                }
                break
              default:
                entry.text = part.text ?? ""
            }

            writeJSONL(sessionID, entry)
            break
          }

          case "session.status": {
            const sp = p?.properties ?? p
            if (sp?.status?.type !== "idle") break
            const sid = sp?.sessionID ?? currentSessionID
            if (!sid) break

            if (turn) turn.endTime = ts()

            writeJSONL(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "turn.complete",
            })

            // Write session header YAML once, then per-turn docs
            const yamlPath = join(LOG_BASE, `${sid}.yaml`)
            if (!headerWritten) {
              writeYAMLDoc(yamlPath, {
                session: { id: sid, created: sessionCreated },
                model: sessionModel,
              })
              headerWritten = true
            }

            if (turn && turn.userText) {
              writeYAMLDoc(yamlPath, turn.toYAMLDoc())
            }

            turn = null
            break
          }

          case "session.compacted": {
            const sid = p?.sessionID ?? currentSessionID
            if (!sid) break
            writeJSONL(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: "session.compacted",
            })
            break
          }

          case "session.deleted":
          case "server.instance.disposed": {
            const info = p?.info
            const sid = event.type === "session.deleted"
              ? (info?.id ?? currentSessionID)
              : currentSessionID
            if (!sid) break
            writeJSONL(sid, {
              timestamp: ts(),
              sessionID: sid,
              type: event.type === "session.deleted" ? "session.deleted" : "server.shutdown",
            })
            if (currentSessionID === sid) currentSessionID = null
            break
          }
        }
      } catch {
        // Plugin failures must not crash OpenCode
      }
    },
  }
}
